const envelope = $input.first().json;
const plan = envelope.body ?? envelope;
const headers = envelope.headers ?? {};
const fail = (message) => { throw new Error(`FCR_JIRA_PLAN_REJECTED: ${message}`); };
const isObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const fullSha = /^[0-9a-f]{40}$/i;
const projectKey = /^[A-Z][A-Z0-9_]{1,19}$/;
const issueKey = /^[A-Z][A-Z0-9_]{1,19}-[1-9][0-9]*$/;
if (!isObject(plan)) fail('plan must be an object');
if (plan.contract !== 'founder-control-room/jira-work-automation@v1') fail('unsupported contract');
if (!/^fcr-jira-v1:[0-9a-f]{64}$/i.test(String(plan.idempotencyKey ?? ''))) fail('invalid idempotency key');
if (String(headers['idempotency-key'] ?? '') !== plan.idempotencyKey) fail('transport idempotency key mismatch');
if (String(headers['x-fcr-jira-automation-contract'] ?? '') !== 'v1') fail('transport contract header mismatch');
if (!fullSha.test(String(plan.runtimeHeadSha ?? ''))) fail('exact runtime head SHA required');
if (!isObject(plan.issue)) fail('issue snapshot required');
if (!projectKey.test(String(plan.issue.projectKey ?? ''))) fail('invalid project key');
if (!issueKey.test(String(plan.issue.issueKey ?? ''))) fail('invalid issue key');
if (String(plan.issue.issueKey).split('-')[0] !== plan.issue.projectKey) fail('issue/project identity mismatch');
if (String(plan.issue.toStatus ?? '').trim().toLowerCase() !== 'in progress') fail('only In Progress work is supported');
const updatedAt = Date.parse(String(plan.issue.updatedAt ?? ''));
const observedAt = Date.parse(String(plan.issue.observedAt ?? ''));
if (!Number.isFinite(updatedAt) || !Number.isFinite(observedAt) || updatedAt > observedAt) fail('invalid observation window');
if (!Array.isArray(plan.actions) || plan.actions.length !== 1) fail('exactly one bounded action is required per observation');
if (!isObject(plan.authority)) fail('authority envelope required');
for (const field of ['transitionIssue', 'closeIssue', 'deleteIssue', 'mutateProjectSettings']) { if (plan.authority[field] !== false) fail(`forbidden authority opened: ${field}`); }
const actionTypes = new Set();
for (const action of plan.actions) {
  if (!isObject(action) || (action.type !== 'assign-owner' && action.type !== 'comment-stale')) fail('unsupported action');
  if (actionTypes.has(action.type)) fail('duplicate action type');
  actionTypes.add(action.type);
  if (action.type === 'assign-owner') {
    if (action.ownerLabel !== 'sekretbip' || typeof action.ownerAccountId !== 'string' || !action.ownerAccountId.trim()) fail('invalid owner mapping');
  } else {
    if (!Number.isInteger(action.staleAfterHours) || action.staleAfterHours <= 0) fail('invalid stale threshold');
    const expectedMessage = `FCR stale-work guard: this item has remained In Progress without an update for at least ${action.staleAfterHours} hours. Add a current status update or move it to the correct workflow state.`;
    if (action.message !== expectedMessage) fail('stale comment content drift');
  }
}
if (Boolean(plan.authority.assignIssue) !== actionTypes.has('assign-owner')) fail('assignment authority/action mismatch');
if (Boolean(plan.authority.commentIssue) !== actionTypes.has('comment-stale')) fail('comment authority/action mismatch');
const material = { contract: plan.contract, idempotencyKey: plan.idempotencyKey, runtimeHeadSha: plan.runtimeHeadSha, issueKey: plan.issue.issueKey, actions: plan.actions };
const bytes = new TextEncoder().encode(JSON.stringify(material));
const digest = await crypto.subtle.digest('SHA-256', bytes);
const hex = [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, '0')).join('');
return [{ json: { plan, expectedReceiptId: `fcr-jira-receipt-v1:${hex}` } }];

const jira = $input.first().json;
const validated = $('Validate FCR Plan').first().json;
const plan = validated.plan;
const fail = (message) => { throw new Error(`FCR_JIRA_STATE_DRIFT: ${message}`); };
const normalizeStatus = (value) => String(value ?? '').trim().toLowerCase();
const actualStatus = jira?.fields?.status?.name;
const actualAssignee = jira?.fields?.assignee?.accountId ?? null;
const actualUpdatedMs = Date.parse(String(jira?.fields?.updated ?? ''));
const plannedUpdatedMs = Date.parse(plan.issue.updatedAt);
if (normalizeStatus(actualStatus) !== normalizeStatus(plan.issue.toStatus)) fail('status changed after FCR observation');
if ((actualAssignee || null) !== (plan.issue.assigneeAccountId || null)) fail('assignee changed after FCR observation');
if (!Number.isFinite(actualUpdatedMs) || actualUpdatedMs !== plannedUpdatedMs) fail('updated timestamp changed after FCR observation');
const action = plan.actions[0];
if (action.type === 'assign-owner') {
  if (actualAssignee !== null) fail('assignment no longer unowned');
  return [{ json: { expectedReceiptId: validated.expectedReceiptId, idempotencyKey: plan.idempotencyKey, actionType: action.type, issueKey: plan.issue.issueKey, request: { method: 'PUT', path: `/rest/api/3/issue/${encodeURIComponent(plan.issue.issueKey)}`, body: { fields: { assignee: { accountId: action.ownerAccountId } } } } } }];
}
const observedAtMs = Date.parse(plan.issue.observedAt);
const ageHours = (observedAtMs - actualUpdatedMs) / 3600000;
if (!Number.isFinite(ageHours) || ageHours < action.staleAfterHours) fail('stale threshold no longer satisfied');
return [{ json: { expectedReceiptId: validated.expectedReceiptId, idempotencyKey: plan.idempotencyKey, actionType: action.type, issueKey: plan.issue.issueKey, request: { method: 'POST', path: `/rest/api/3/issue/${encodeURIComponent(plan.issue.issueKey)}/comment`, body: { body: { type: 'doc', version: 1, content: [{ type: 'paragraph', content: [{ type: 'text', text: action.message }] }] } } } } }];

const validated = $('Validate FCR Plan').first().json;
const plan = validated.plan;
const results = $input.all();
if (results.length !== 1 || plan.actions.length !== 1) throw new Error('FCR_JIRA_MUTATION_COUNT_MISMATCH');
return [{ json: { receiptId: validated.expectedReceiptId, contract: 'founder-control-room/jira-work-automation-receipt@v1', idempotencyKey: plan.idempotencyKey, runtimeHeadSha: plan.runtimeHeadSha, issueKey: plan.issue.issueKey, mutatedActions: [plan.actions[0].type] } }];
